<script>document.addEventListener('DOMContentLoaded',()=>{const add=document.getElementById('add-journal-line'),list=document.getElementById('journal-lines');if(!add)return;add.addEventListener('click',()=>{const n=list.children.length;if(n>=100)return;const clone=list.children[0].cloneNode(true);clone.querySelectorAll('[name]').forEach(el=>{el.name=el.name.replace(/lines\[\d+\]/,'lines['+n+']');if(el.type==='number')el.value='0';});list.appendChild(clone);});});</script>
